import { I, dish } from "./catalog-kit.ts";
import type { Recipe } from "./types";

function so(
  id: string,
  name: string,
  tags: string[],
  protein: Recipe["protein"],
  plate: Recipe["plate"],
  minutes: number,
  description: string,
  ingredients: Recipe["ingredients"],
  steps: string[],
  aliases: string[] = [],
  nutrition?: Recipe["nutrition"],
  extra?: Partial<Pick<Recipe, "servings" | "photo">>,
): Recipe {
  return dish({
    id,
    name,
    description,
    minutes,
    protein,
    plate,
    cuisine: "Southern",
    tags: Array.from(new Set(["southern", ...tags])),
    aliases,
    ingredients,
    steps,
    nutrition,
    // No default photo. Asserting `/food/<id>.jpg` here claims a file exists
    // whether or not one does, and outranks the generated manifest, which is
    // the only thing that actually knows. A dish without a photograph should
    // fall through to its drawn plate, not to a broken image.
    ...(extra?.photo ? { photo: extra.photo } : {}),
    ...(extra?.servings ? { servings: extra.servings } : {}),
  });
}

